insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-keep-passing-record-no-read-s647','decision','A passing filed record is kept when a read produces no record for its program','The S647 conductor, #3202: a passing record is never deleted by a read that produced none for its program (not_found, page_claimed); it is kept and named (keep_no_read, free step refile-kept). A failing record with no new read is dropped, and so is a program outside Active and Approved. 19577, in teach-out, dropped; 24432 held as a wrong-tab read (its page names 31597).',array['program-requirements','decision'],'proposed','S647, PR 3202, COBIx 6851581238',null,null,'SkyPipit (S647)',date '2026-11-13'),
('d-commons-data-slice1-on-relayed-go-s647','decision','The Commons data dashboard slice 1 shipped on Sam''s relayed words; later slices wait','The S647 conductor, #3215 to #3222 (merged bc376fe5): slice 1 at #commons/data was built and merged on COBIx''s reading (6851872697) of Sam''s relayed 2:53 AM PT words as covering slice 1 through the normal path. Later slices and the College view are not covered and wait for Sam''s go.',array['commons','decision'],'proposed','S647, PR 3222, issue 3215',null,null,'SkyPipit (S647)',date '2026-11-13'),
('d-receipt-is-a-plain-statement-s647','procedure','A data receipt is one plain statement whose writes hang on one guard CTE','S647: the repo''s Supabase guard refuses do blocks, so the Library receipt''s first form was refused. A worker rewrote it as one with statement whose three writes hang on one guard, proved on a scratch Postgres; a test now refuses a do block in a forward receipt.',array['supabase','procedure'],'proposed','S647, PR 3216',null,null,'SkyPipit (S647)',date '2026-11-13'),
('p-401-was-the-database-s647','pitfall','The extraction function answers 401 when the database is down','S647: the caller check reads allowed_reviewers and answers 401 on any upstream failure, so an outage reads as a bad key. Glendale''s paid slow read 43384599013 had all 135 calls answer 401 (about $9.33, as reported). COBIx''s fix, 503 on an upstream error, changes a deployed function and waits for Sam''s deploy word.',array['program-requirements','pitfall'],'proposed','S647, PR 3202',null,null,'SkyPipit (S647)',date '2026-11-13'),
('d-stopped-session-taken-over-s647','procedure','How a firing reads a stopped session and takes the queue','S647: the 08:55Z session stopped at about 10:12Z with no handoff. The 11:12Z firing read it from a green PR with COBIx''s check unmerged for an hour and every thread quiet at once, opened draft #3221 before any other write, and took the queue under the same number. Refresh that PR within each half hour.',array['scheduled-sessions','procedure'],'proposed','S647, PR 3221; scheduled_sessions.md',null,null,'SkyPipit (S647)',date '2026-11-13'),
('d-rescore-text-checked-from-artifacts-s647','decision','Captured page text is checked from run artifacts, by COBIx','The S647 conductor, #3207: captured text lives only in run artifacts. The session''s network refuses artifact storage and the session left the refusal alone; COBIx downloaded the two artifacts and read the captured text (6851481011) before the rescore merged (5a88b2a5).',array['program-requirements','decision'],'proposed','S647, PR 3207',null,null,'SkyPipit (S647)',date '2026-11-13'),
('sam-commons-data-front-porch-2026-11-13','decision','Sam: the Commons data mock to Sky, in prod on the front porch by morning','Sam, relayed by COBIx on #3215 (2:52 and 2:53 AM PT), verbatim: "can you get the mock to sky and all the background info he needs to understand everything" and "hopefully he can just blend this into his queue work and when i wake up in a few hours he will have it in prod on our commons front porch."',array['commons','decision'],'verified','Sam, relayed by COBIx on #3215','Sam Lee',now(),'SkyPipit (S647)',date '2026-11-13'),
('sam-cor-description-from-slos-2026-11-13','decision','Sam: complete course descriptions from SLOs and objectives in the COR queue','Sam, relayed by COBIx on #3219 (1:52 AM PT), verbatim: "coci does not have reliable course descriptions, especially for noncredit so we will need to add a procedure in our cor queue where we grab the slos and objectives to complete the description field when needed--this will really help with all those thousands of nc standalone courses we have in the system"',array['commons','decision'],'verified','Sam, relayed by COBIx on #3219','Sam Lee',now(),'SkyPipit (S647)',date '2026-11-13'),
('sam-data-element-dictionary-2026-11-13','decision','Sam: a data element dictionary for each dataset in the plan','Sam, relayed by COBIx on #3220, verbatim: "We should have in our plan documentation (data element dictionary) for each dataset and the procedures currently used to procure or connect to the data and the planned procedural improvements for efficiency and accuracy and who owns the data."',array['commons','decision'],'verified','Sam, relayed by COBIx on #3220','Sam Lee',now(),'SkyPipit (S647)',date '2026-11-13')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyPipit (S647)', 'create', 'checkpoint auto-write (S647, 2026-11-13)', to_jsonb(m)
from public.cpl_memory m where m.author = 'SkyPipit (S647)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.author = 'SkyPipit (S647)' group by m.slug order by m.slug;
